// Create text file - check if AI content exists or trigger S1 generation
const reportData = $input.first().json;

console.log('=== CREATING FINAL REPORT TEXT FILE ===');
console.log('Report data received:', reportData);

const companyName = reportData.company_name || 'Unknown_Company';
const companyId = reportData.company_id || 'unknown_id';
const status = reportData.status || 'unknown';
const createdAt = reportData.created_at || new Date().toISOString();
const reportDate = new Date().toISOString().split('T')[0];

// Check if we have AI-generated content
if ((!reportData.executive_summary && !reportData.legal_disclaimers_reliance_limitations && !reportData.section3_content) || status === 'pending_ai_generation') {
  console.log('⚠️ No AI-generated content found - S1/S2/S3 subworkflows need to run first');
  console.log('Creating status file to indicate AI generation is needed');

  const statusContent = `Due Diligence Report - Status\n${'='.repeat(80)}\n\nCompany: ${companyName}\nCompany ID: ${companyId}\nGenerated: ${reportDate}\nStatus: AI Generation Required\n\n${'='.repeat(80)}\n\nSTATUS: WAITING FOR AI GENERATION\n\nThe S1/S2/S3 subworkflows need to run to generate report content.\nThis file will be updated once the AI agent completes the analysis.\n\nNext Steps:\n1. S1/S2/S3 subworkflows will analyze company data\n2. AI agent will generate professional report content\n3. Content will be saved to database\n4. This file will be replaced with actual AI-generated content\n\n${'='.repeat(80)}\nEnd of Status Update\nGenerated by Action Labs Due Diligence System\n`;

  const fileName = `${companyName.replace(/[^a-zA-Z0-9]/g, '_')}_Report_STATUS_${reportDate}.txt`;

  console.log(`✅ Created status file: ${fileName}`);

  return [{
    json: {
      company_id: companyId,
      company_name: companyName,
      file_name: fileName,
      content: statusContent,
      content_length: statusContent.length,
      created_at: reportDate,
      status: 'status_file_created',
      source: 'waiting_for_ai'
    },
    binary: {
      data: {
        data: Buffer.from(statusContent, 'utf8').toString('base64'),
        mimeType: 'text/plain',
        fileName: fileName
      }
    }
  }];
}

// We have AI-generated content
const section1Content = reportData.executive_summary || '';
const section2Content = reportData.legal_disclaimers_reliance_limitations || '';
const section3Content = reportData.section3_content || '';
const section4Content = reportData.section4_content || '';
const section5Content = reportData.section5_content || '';
const section6Content = reportData.section6_content || '';
const section7Content = reportData.section7_content || '';
const section8Content = reportData.section8_content || '';
const sectionsCompleted = reportData.sections_completed || 0;

console.log(`✅ Found AI-generated content for: ${companyName}`);
console.log(`Section 1 length: ${section1Content.length} characters`);
console.log(`Section 2 length: ${section2Content.length} characters`);
console.log(`Section 3 length: ${section3Content.length} characters`);
console.log(`Section 4 length: ${section4Content.length} characters`);
console.log(`Section 5 length: ${section5Content.length} characters`);
console.log(`Section 6 length: ${section6Content.length} characters`);
console.log(`Section 7 length: ${section7Content.length} characters`);
console.log(`Section 8 length: ${section8Content.length} characters`);
console.log(`Sections completed: ${sectionsCompleted}`);
console.log(`Status: ${status}`);

// Create comprehensive text file with all available content
let allContent = '';
if (section1Content) {
  allContent += `SECTION 1: EXECUTIVE SUMMARY & KEY FINDINGS\n${'='.repeat(80)}\n\n${section1Content}\n\n${'='.repeat(80)}\n\n`;
}
if (section2Content) {
  allContent += `SECTION 2: LEGAL DISCLAIMERS & RELIANCE LIMITATIONS\n${'='.repeat(80)}\n\n${section2Content}\n\n${'='.repeat(80)}\n\n`;
}
if (section3Content) {
  allContent += `SECTION 3: METHODOLOGY & SOURCE VALIDATION PROTOCOLS\n${'='.repeat(80)}\n\n${section3Content}\n\n${'='.repeat(80)}\n\n`;
}
if (section4Content) {
  allContent += `SECTION 4: BUSINESS OVERVIEW\n${'='.repeat(80)}\n\n${section4Content}\n\n${'='.repeat(80)}\n\n`;
}
if (section5Content) {
  allContent += `SECTION 5: COMPANY OVERVIEW\n${'='.repeat(80)}\n\n${section5Content}\n\n${'='.repeat(80)}\n\n`;
}
if (section6Content) {
  allContent += `SECTION 6: BUSINESS MODEL\n${'='.repeat(80)}\n\n${section6Content}\n\n${'='.repeat(80)}\n\n`;
}
if (section7Content) {
  allContent += `SECTION 7: PRODUCTS & SERVICES\n${'='.repeat(80)}\n\n${section7Content}\n\n${'='.repeat(80)}\n\n`;
}
if (section8Content) {
  allContent += `SECTION 8: TARGET MARKET & COMPETITIVE SET\n${'='.repeat(80)}\n\n${section8Content}\n\n${'='.repeat(80)}\n\n`;
}

const textFileContent = `Due Diligence Report - Complete Sections\n${'='.repeat(80)}\n\nCompany: ${companyName}\nCompany ID: ${companyId}\nGenerated: ${reportDate}\nAI Generated: ${createdAt}\nSections Completed: ${sectionsCompleted}\nStatus: ${status}\nSource: AI Subworkflows\n\n${'='.repeat(80)}\n\n${allContent}\n${'='.repeat(80)}\nEnd of Complete Report\nGenerated by Action Labs Due Diligence System\nAI Content Generated by Subworkflows\n`;

const fileName = `${companyName.replace(/[^a-zA-Z0-9]/g, '_')}_Complete_DD_Report_${reportDate}.txt`;

console.log(`✅ Created AI-generated text file: ${fileName}`);
console.log(`File contains AI-generated content from S1-S8 subworkflows`);
console.log(`Total file length: ${textFileContent.length} characters`);

// Return data in Code node format (array of items)
return [{
  json: {
    company_id: companyId,
    company_name: companyName,
    file_name: fileName,
    content: textFileContent,
    content_length: textFileContent.length,
    ai_content_length: section1Content.length + section2Content.length + section3Content.length + section4Content.length + section5Content.length + section6Content.length + section7Content.length + section8Content.length,
    sections_completed: sectionsCompleted,
    created_at: reportDate,
    status: 'ai_content_ready',
    source: 'ai_subworkflows'
  },
  binary: {
    data: {
      data: Buffer.from(textFileContent, 'utf8').toString('base64'),
      mimeType: 'text/plain',
      fileName: fileName
    }
  }
}];
